+  let owner = options.isolated === true ? undefined : state.activation;
+  if (owner === undefined) {
+    const instrumentation = drizzleInstrumentationOf(database);
+    owner = ManagedRuntime.make(authLiveLayer({ options: state.options, database, basePath }).pipe(Layer.provide(Layer.succeedContext(instrumentation))));
+    if (options.isolated !== true) state.activation = owner;
+  }
+  const currentOwner = owner;
+  try {
+    return await runAuthPromise(currentOwner, Effect.flatMap(AuthService, (auth) => Effect.sync(() => nativeAdapter(currentOwner, auth.native))));
+  } catch (error) {
+    if (state.activation === currentOwner) state.activation = undefined;
+    await currentOwner.dispose();
+    throw error;
+  }
