+it.effect("configured tracers redact named Auth spans without changing native values or causes", () =>
+  Effect.gen(function* () {
+    const database = yield* authTestDatabase();
+    const spans: Tracer.NativeSpan[] = [];
+    const tracer = Tracer.make({ span(options) {
+      const span = new Tracer.NativeSpan(options);
+      spans.push(span);
+      return span;
+    } });
+    const secret = "auth-native-secret-cookie-password-token";
+    const failure = new Error(secret);
+    let failHandler = false;
+    const native = nativeAuthStub({ handler: async () => {
+      if (failHandler) throw failure;
+      return new Response(secret);
+    }, session: async () => { throw failure; } });
+    yield* Effect.gen(function* () {
