++      const response = yield* service.handler(new Request("http://localhost/api/auth/get-session"));
+      expect(yield* Effect.promise(() => response.text())).toBe(secret);
+      failHandler = true;
+      const handlerExit = yield* Effect.exit(service.handler(new Request("http://localhost/api/auth/get-session")));
+      const apiExit = yield* Effect.exit(service.api("getSession", []));
+      for (const exit of [handlerExit, apiExit]) {
+        expect(Exit.isFailure(exit)).toBe(true);
+        if (Exit.isFailure(exit)) {
+          const reason = Cause.squash(exit.cause);
+          expect(reason).toBeInstanceOf(AuthFailure);
+          expect((reason as AuthFailure).cause).toBe(failure);
+        }
+      }
+    }).pipe(Effect.provide(authTestLayer({ database, options: { secret }, basePath: "/api/auth" }, Effect.succeed(native))),
